services:
  stack-auth-db:
    image: postgres:17
    environment:
      - POSTGRES_USER=${POSTGRES_USER}
      - POSTGRES_PASSWORD=[REDACTED]}
      - POSTGRES_DB=${POSTGRES_DB}
    volumes:
      - stack-auth-db-data:/var/lib/postgresql/data
    healthcheck:
      test: ["CMD-SHELL", "pg_isready", "-d", "db_prod"]
      interval: 10s
      timeout: 60s
      retries: 5
      start_period: 80s

  stack-auth:
    image: stackauth/server:latest
    environment:
      - POSTGRES_USER=${POSTGRES_USER}
      - POSTGRES_PASSWORD=[REDACTED]}
      - POSTGRES_DB=${POSTGRES_DB}
      - NEXT_PUBLIC_STACK_API_URL=${NEXT_PUBLIC_STACK_API_URL}
      - NEXT_PUBLIC_STACK_DASHBOARD_URL=${NEXT_PUBLIC_STACK_DASHBOARD_URL}
      - STACK_DATABASE_CONNECTION_STRING=${STACK_DATABASE_CONNECTION_STRING}
      - STACK_DIRECT_DATABASE_CONNECTION_STRING=${STACK_DIRECT_DATABASE_CONNECTION_STRING}
      - STACK_SERVER_SECRET=[REDACTED]}
      - STACK_SEED_INTERNAL_PROJECT_ALLOW_LOCALHOST=${STACK_SEED_INTERNAL_PROJECT_ALLOW_LOCALHOST}
      - STACK_SEED_INTERNAL_PROJECT_SIGN_UP_ENABLED=${STACK_SEED_INTERNAL_PROJECT_SIGN_UP_ENABLED}
      - STACK_RUN_MIGRATIONS=${STACK_RUN_MIGRATIONS}
      - STACK_RUN_SEED_SCRIPT=${STACK_RUN_SEED_SCRIPT}
      - STACK_EMAIL_HOST=${STACK_EMAIL_HOST}
    depends_on:
      stack-auth-db:
        condition: service_healthy


volumes:
  stack-auth-db-data:

services:
  tor:
    image: domistyle/tor-browser
    restart: always
    expose:
      - 5800
      - 5900
    environment:
      DISPLAY_WIDTH: ${DISPLAY_WIDTH}
      DISPLAY_HEIGHT: ${DISPLAY_HEIGHT}
      KEEP_APP_RUNNING: ${KEEP_APP_RUNNING}
      TZ: ${TZ}

services:
  wise-mcp:
    image: ghcr.io/blanketbyte/wise-mcp:1.1.1
    restart: unless-stopped
    expose:
      - 3000
    environment:
      - PUBLIC_URL=${PUBLIC_URL}
      - TOKEN_ENCRYPTION_KEY=${TOKEN_ENCRYPTION_KEY}
      - ALLOWED_WISE_USERS=${ALLOWED_WISE_USERS}
      - WRITES_ENABLED=${WRITES_ENABLED}
    volumes:
      - wise-mcp-data:/data

volumes:
  wise-mcp-data: {}

services:
  crawl4ai:
    image: unclecode/crawl4ai:latest
    restart: unless-stopped
    shm_size: 1g
    expose:
      - 11235
    environment:
      - LLM_PROVIDER=${LLM_PROVIDER}
      - OPENAI_API_KEY=[REDACTED]}
      - ANTHROPIC_API_KEY=[REDACTED]}
      - DEEPSEEK_API_KEY=[REDACTED]}
      - GROQ_API_KEY=[REDACTED]}
      - TOGETHER_API_KEY=[REDACTED]}
      - MISTRAL_API_KEY=[REDACTED]}
      - GEMINI_API_TOKEN=[REDACTED]}
    healthcheck:
      test: ["CMD", "curl", "-f", "http://localhost:11235/health"]
      interval: 30s
      timeout: 10s
      retries: 3
